// This file was generated by Prisma, and assumes you have installed the following:
// bun add --dev prisma dotenv
//
// Keep this file self-contained: it ships in release/deploy artifacts that copy only
// prisma.config.ts and prisma/, so it may import nothing but 'dotenv' and 'prisma/config'.
import { config } from 'dotenv';
import { defineConfig } from 'prisma/config';

// Same order and no-shadow rule as scripts/load-local-env.ts: real process
// variables win, then .env.local, then .env.
config({ path: ['.env.local', '.env'], quiet: true });

/** Prisma CLI commands that never open a database connection. */
export const OFFLINE_PRISMA_COMMANDS = new Set([
  'generate',
  'validate',
  'format',
  'version',
  'help',
]);

function prismaCommand(argv: readonly string[]): string | undefined {
  for (let index = 2; index < argv.length; index++) {
    const arg = argv[index];
    // Separate option values are paths/metadata, even if they match a command.
    // The --option=value form is already skipped by the flag check below.
    if (['--config', '--schema', '--telemetry-information'].includes(arg)) {
      index++;
      continue;
    }
    if (!arg.startsWith('-')) return arg;
  }
  return undefined;
}

/**
 * Resolve the Prisma datasource URL. Database commands (migrate, db, studio, …)
 * fail fast without credentials; offline commands such as `prisma generate`
 * (postinstall, Docker builder) must keep working with no database configured.
 */
export function resolvePrismaDatasourceUrl(
  environment: NodeJS.ProcessEnv = process.env,
  argv: readonly string[] = process.argv
): string | undefined {
  const migrationUrl = environment['MIGRATION_DATABASE_URL']?.trim();
  if (migrationUrl) return migrationUrl;
  const databaseUrl = environment['DATABASE_URL']?.trim() || undefined;
  const command = prismaCommand(argv);
  const offline =
    command === undefined
      ? argv.some((arg) => ['-v', '--version', '-h', '--help'].includes(arg))
      : OFFLINE_PRISMA_COMMANDS.has(command);
  if (offline || databaseUrl) return databaseUrl;
  throw new Error(
    'Missing required environment variable: DATABASE_URL. Searched .env.local and .env (existing process environment variables take precedence).'
  );
}

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
    seed: 'bunx tsx prisma/seed.ts',
  },
  datasource: {
    // Migrations use the elevated URL when it is set. The running server reads
    // DATABASE_URL only (src/lib/db.ts) and must stay NOSUPERUSER NOBYPASSRLS.
    // Offline commands (prisma generate in postinstall/Docker) need no credentials.
    url: resolvePrismaDatasourceUrl(),
    shadowDatabaseUrl: process.env['SHADOW_DATABASE_URL'],
  },
});
